fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // We assume 0 <= idx <= arr.len(), as stated.
    let n = arr.len();
    let mut result = Vec::with_capacity(n + 1);

    // Move elements from arr into result, inserting `value` when we reach `idx`.
    for (i, elem) in arr.into_iter().enumerate() {
        if i == idx {
            result.push(value);
        }
        result.push(elem);
    }

    // If idx == n, we never inserted inside the loop, so do it now at the end.
    if idx == n {
        result.push(value);
    }

    result
}

